  1	package com.pousadamarealta;
  2	
  3	import com.fasterxml.jackson.databind.ObjectMapper;
  4	import com.pousadamarealta.api.*;
  5	import com.pousadamarealta.database.Database;
  6	import com.pousadamarealta.database.MessageRepository;
  7	import com.pousadamarealta.database.ReservationRepository;
  8	import com.pousadamarealta.database.RoomRepository;
  9	import com.pousadamarealta.models.Reservation;
 10	import com.pousadamarealta.models.Room;
 11	import com.pousadamarealta.rateplans.RatePlan;
 12	import com.pousadamarealta.services.ReceiptService;
 13	import com.pousadamarealta.services.ReportService;
 14	import com.pousadamarealta.services.ReservationService;
 15	import io.javalin.Javalin;
 16	import io.javalin.http.HttpStatus;
 17	import java.math.BigDecimal;
 18	import java.sql.SQLException;
 19	import java.time.LocalDate;
 20	import java.time.YearMonth;
 21	import java.time.format.DateTimeFormatter;
 22	import java.util.stream.Collectors;
 23	
 24	public class Main {
 25	    private static final ObjectMapper mapper = new ObjectMapper();
 26	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd");
 27	
 28	    public static void main(String[] args) throws SQLException {
 29	        // Initialize database
 30	        String dbUrl = System.getenv("DB_URL");
 31	        String dbUser = System.getenv("DB_USER");
 32	        String dbPassword = System.getenv("DB_PASSWORD");
 33	
 34	        if (dbUrl == null || dbUser == null || dbPassword == null) {
 35	            System.err.println("Missing required environment variables: DB_URL, DB_USER, DB_PASSWORD");
 36	            System.exit(1);
 37	        }
 38	
 39	        Database.initialize(dbUrl, dbUser, dbPassword);
 40	        RoomRepository.initializeRooms();
 41	
 42	        // Initialize server
 43	        String portEnv = System.getenv("PORT");
 44	        int port = portEnv != null ? Integer.parseInt(portEnv) : 7070;
 45	
 46	        Javalin app = Javalin.create();
 47	
 48	        // GET /rooms
 49	        app.get("/rooms", ctx -> {
 50	            try {
 51	                var rooms = RoomRepository.findAll();
 52	                var response = rooms.stream()
 53	                    .map(RoomResponse::new)
 54	                    .collect(Collectors.toList());
 55	                ctx.json(response);
 56	            } catch (SQLException e) {
 57	                ctx.status(500).json(new ApiError("DATABASE_ERROR", e.getMessage()));
 58	            }
 59	        });
 60	
 61	        // POST /reservations
 62	        app.post("/reservations", ctx -> {
 63	            try {
 64	                ReservationRequest request = ctx.bodyAsClass(ReservationRequest.class);
 65	
 66	                if (request.roomNumber == 0 || request.guestName == null || request.guestEmail == null ||
 67	                    request.guestCpf == null || request.checkIn == null || request.checkOut == null ||
 68	                    request.guests == 0 || request.ratePlan == null) {
 69	                    ctx.status(400).json(new ApiError("INVALID_REQUEST", "Missing required fields"));
 70	                    return;
 71	                }
 72	
 73	                if (request.guests < 1) {
 74	                    ctx.status(400).json(new ApiError("INVALID_REQUEST", "Guest count must be at least 1"));
 75	                    return;
 76	                }
 77	
 78	                // Parse dates
 79	                LocalDate checkIn, checkOut;
 80	                try {
 81	                    checkIn = LocalDate.parse(request.checkIn, DATE_FORMAT);
 82	                    checkOut = LocalDate.parse(request.checkOut, DATE_FORMAT);
 83	                } catch (Exception e) {
 84	                    ctx.status(400).json(new ApiError("INVALID_REQUEST", "Invalid date format"));
 85	                    return;
 86	                }
 87	
 88	                if (!checkOut.isAfter(checkIn)) {
 89	                    ctx.status(400).json(new ApiError("INVALID_REQUEST", "Check-out date must be after check-in date"));
 90	                    return;
 91	                }
 92	
 93	                // Validate room exists
 94	                Room room = RoomRepository.findById(request.roomNumber);
 95	                if (room == null) {
 96	                    ctx.status(404).json(new ApiError("ROOM_NOT_FOUND", "Room not found"));
 97	                    return;
 98	                }
 99	
100	                // Create reservation
101	                Reservation reservation = ReservationService.createReservation(
102	                    request.roomNumber,
103	                    request.guestName,
104	                    request.guestEmail,
105	                    request.guestCpf,
106	                    checkIn,
107	                    checkOut,
108	                    request.guests,
109	                    request.ratePlan,
110	                    request.companyCode
111	                );
112	
113	                ctx.status(201).json(new ReservationResponse(reservation));
114	            } catch (RatePlan.InvalidRatePlanException e) {
115	                ctx.status(400).json(new ApiError("INVALID_REQUEST", e.getMessage()));
116	            } catch (IllegalArgumentException e) {
117	                String message = e.getMessage();
118	                if (message.contains("Room not available")) {
119	                    ctx.status(409).json(new ApiError("ROOM_UNAVAILABLE", message));
120	                } else if (message.contains("capacity")) {
121	                    ctx.status(422).json(new ApiError("CAPACITY_EXCEEDED", message));
122	                } else if (message.contains("Rate plan")) {
123	                    ctx.status(400).json(new ApiError("INVALID_REQUEST", message));
124	                } else if (message.contains("Room not found")) {
125	                    ctx.status(404).json(new ApiError("ROOM_NOT_FOUND", message));
126	                } else {
127	                    ctx.status(400).json(new ApiError("INVALID_REQUEST", message));
128	                }
129	            } catch (SQLException e) {
130	                ctx.status(500).json(new ApiError("DATABASE_ERROR", e.getMessage()));
131	            }
132	        });
133	
134	        // GET /reservations/{id}
135	        app.get("/reservations/{id}", ctx -> {
136	            try {
137	                int id = Integer.parseInt(ctx.pathParam("id"));
138	                Reservation reservation = ReservationRepository.findById(id);
139	                if (reservation == null) {
140	                    ctx.status(404).json(new ApiError("RESERVATION_NOT_FOUND", "Reservation not found"));
141	                    return;
142	                }
143	                ctx.json(new ReservationResponse(reservation));
144	            } catch (NumberFormatException e) {
145	                ctx.status(400).json(new ApiError("INVALID_REQUEST", "Invalid reservation ID"));
146	            } catch (SQLException e) {
147	                ctx.status(500).json(new ApiError("DATABASE_ERROR", e.getMessage()));
148	            }
149	        });
150	
151	        // POST /reservations/{id}/confirmation
152	        app.post("/reservations/{id}/confirmation", ctx -> {
153	            try {
154	                int id = Integer.parseInt(ctx.pathParam("id"));
155	                Reservation reservation = ReservationService.confirmReservation(id);
156	                ctx.json(new ReservationResponse(reservation));
157	            } catch (NumberFormatException e) {
158	                ctx.status(400).json(new ApiError("INVALID_REQUEST", "Invalid reservation ID"));
159	            } catch (IllegalArgumentException e) {
160	                ctx.status(404).json(new ApiError("RESERVATION_NOT_FOUND", e.getMessage()));
161	            } catch (IllegalStateException e) {
162	                ctx.status(409).json(new ApiError("OPERATION_NOT_ALLOWED", e.getMessage()));
163	            } catch (SQLException e) {
164	                ctx.status(500).json(new ApiError("DATABASE_ERROR", e.getMessage()));
165	            }
166	        });
167	
168	        // POST /reservations/{id}/cancellation
169	        app.post("/reservations/{id}/cancellation", ctx -> {
170	            try {
171	                int id = Integer.parseInt(ctx.pathParam("id"));
172	                Reservation reservation = ReservationService.cancelReservation(id);
173	                ctx.json(new ReservationResponse(reservation));
174	            } catch (NumberFormatException e) {
175	                ctx.status(400).json(new ApiError("INVALID_REQUEST", "Invalid reservation ID"));
176	            } catch (IllegalArgumentException e) {
177	                ctx.status(404).json(new ApiError("RESERVATION_NOT_FOUND", e.getMessage()));
178	            } catch (IllegalStateException e) {
179	                ctx.status(409).json(new ApiError("OPERATION_NOT_ALLOWED", e.getMessage()));
180	            } catch (SQLException e) {
181	                ctx.status(500).json(new ApiError("DATABASE_ERROR", e.getMessage()));
182	            }
183	        });
184	
185	        // POST /reservations/{id}/check-in
186	        app.post("/reservations/{id}/check-in", ctx -> {
187	            try {
188	                int id = Integer.parseInt(ctx.pathParam("id"));
189	                Reservation reservation = ReservationService.checkIn(id);
190	                ctx.json(new ReservationResponse(reservation));
191	            } catch (NumberFormatException e) {
192	                ctx.status(400).json(new ApiError("INVALID_REQUEST", "Invalid reservation ID"));
193	            } catch (IllegalArgumentException e) {
194	                ctx.status(404).json(new ApiError("RESERVATION_NOT_FOUND", e.getMessage()));
195	            } catch (IllegalStateException e) {
196	                ctx.status(409).json(new ApiError("OPERATION_NOT_ALLOWED", e.getMessage()));
197	            } catch (SQLException e) {
198	                ctx.status(500).json(new ApiError("DATABASE_ERROR", e.getMessage()));
199	            }
200	        });
201	
202	        // POST /reservations/{id}/check-out
203	        app.post("/reservations/{id}/check-out", ctx -> {
204	            try {
205	                int id = Integer.parseInt(ctx.pathParam("id"));
206	                Reservation reservation = ReservationService.checkOut(id);
207	                Room room = RoomRepository.findById(reservation.roomNumber);
208	                ctx.json(new ReceiptResponse(reservation, room.type));
209	            } catch (NumberFormatException e) {
210	                ctx.status(400).json(new ApiError("INVALID_REQUEST", "Invalid reservation ID"));
211	            } catch (IllegalArgumentException e) {
212	                ctx.status(404).json(new ApiError("RESERVATION_NOT_FOUND", e.getMessage()));
213	            } catch (IllegalStateException e) {
214	                ctx.status(409).json(new ApiError("OPERATION_NOT_ALLOWED", e.getMessage()));
215	            } catch (SQLException e) {
216	                ctx.status(500).json(new ApiError("DATABASE_ERROR", e.getMessage()));
217	            }
218	        });
219	
220	        // GET /reservations/{id}/document
221	        app.get("/reservations/{id}/document", ctx -> {
222	            try {
223	                int id = Integer.parseInt(ctx.pathParam("id"));
224	                Reservation reservation = ReservationRepository.findById(id);
225	                if (reservation == null) {
226	                    ctx.status(404).json(new ApiError("RESERVATION_NOT_FOUND", "Reservation not found"));
227	                    return;
228	                }
229	
230	                if (reservation.amountPaid.compareTo(BigDecimal.ZERO) == 0) {
231	                    ctx.status(404).json(new ApiError("RESERVATION_NOT_FOUND", "No document available for unpaid reservations"));
232	                    return;
233	                }
234	
235	                Room room = RoomRepository.findById(reservation.roomNumber);
236	                ctx.json(new ReceiptResponse(reservation, room.type));
237	            } catch (NumberFormatException e) {
238	                ctx.status(400).json(new ApiError("INVALID_REQUEST", "Invalid reservation ID"));
239	            } catch (SQLException e) {
240	                ctx.status(500).json(new ApiError("DATABASE_ERROR", e.getMessage()));
241	            }
242	        });
243	
244	        // GET /messages
245	        app.get("/messages", ctx -> {
246	            try {
247	                var messages = MessageRepository.findAll();
248	                var response = messages.stream()
249	                    .map(MessageResponse::new)
250	                    .collect(Collectors.toList());
251	                ctx.json(response);
252	            } catch (SQLException e) {
253	                ctx.status(500).json(new ApiError("DATABASE_ERROR", e.getMessage()));
254	            }
255	        });
256	
257	        // GET /reports/occupancy
258	        app.get("/reports/occupancy", ctx -> {
259	            try {
260	                String dateParam = ctx.queryParam("date");
261	                if (dateParam == null) {
262	                    ctx.status(400).json(new ApiError("INVALID_REQUEST", "Missing date parameter"));
263	                    return;
264	                }
265	
266	                LocalDate date = LocalDate.parse(dateParam, DATE_FORMAT);
267	                String report = ReportService.generateOccupancyReport(date);
268	                ctx.contentType("text/csv; charset=utf-8").result(report);
269	            } catch (Exception e) {
270	                ctx.status(400).json(new ApiError("INVALID_REQUEST", "Invalid date format"));
271	            }
272	        });
273	
274	        // GET /reports/revenue
275	        app.get("/reports/revenue", ctx -> {
276	            try {
277	                String monthParam = ctx.queryParam("month");
278	                if (monthParam == null) {
279	                    ctx.status(400).json(new ApiError("INVALID_REQUEST", "Missing month parameter"));
280	                    return;
281	                }
282	
283	                YearMonth month = YearMonth.parse(monthParam, DateTimeFormatter.ofPattern("yyyy-MM"));
284	                String report = ReportService.generateRevenueReport(month);
285	                ctx.contentType("text/csv; charset=utf-8").result(report);
286	            } catch (Exception e) {
287	                ctx.status(400).json(new ApiError("INVALID_REQUEST", "Invalid month format"));
288	            }
289	        });
290	
291	        app.start(port);
292	        System.out.println("Server started on port " + port);
293	    }
294	}

