 15	public class ReservationService {
 16	    private static final String CONFIRMATION_EMAIL_SUBJECT = "Reserva confirmada - Pousada Maré Alta";
 17	
 18	    public static Reservation createReservation(
 19	            int roomNumber,
 20	            String guestName,
 21	            String guestEmail,
 22	            String guestCpf,
 23	            LocalDate checkIn,
 24	            LocalDate checkOut,
 25	            int guests,
 26	            String ratePlanName,
 27	            String companyCode
 28	    ) throws SQLException, RatePlan.InvalidRatePlanException {
 29	        // Validate inputs
 30	        if (guests < 1) {
 31	            throw new IllegalArgumentException("Guest count must be at least 1");
 32	        }
 33	
 34	        if (!checkOut.isAfter(checkIn)) {
 35	            throw new IllegalArgumentException("Check-out date must be after check-in date");
 36	        }
 37	
 38	        // Validate room exists
 39	        Room room = RoomRepository.findById(roomNumber);
 40	        if (room == null) {
 41	            throw new IllegalArgumentException("Room not found");
 42	        }
 43	
 44	        // Validate guest count doesn't exceed capacity
 45	        if (guests > room.capacity) {
 46	            throw new IllegalArgumentException("Guest count exceeds room capacity");
 47	        }
 48	
 49	        // Validate rate plan
 50	        RatePlan ratePlan = RatePlanFactory.getPlan(ratePlanName);
 51	        if (ratePlan == null) {
 52	            throw new IllegalArgumentException("Invalid rate plan");
 53	        }
 54	
 55	        // Validate rate plan specific rules
 56	        ratePlan.validateAppliesTo(room, checkIn, checkOut, guests, companyCode);
 57	
 58	        // Check room availability
 59	        var conflictingReservations = ReservationRepository.findByRoomAndDates(roomNumber, checkIn, checkOut);
 60	        if (!conflictingReservations.isEmpty()) {
 61	            throw new IllegalArgumentException("Room not available for these dates");
 62	        }
 63	
 64	        // Calculate price
 65	        RatePlan.PriceCalculation priceCalc;
 66	        if (ratePlan instanceof CorporatePlan) {
 67	            priceCalc = ((CorporatePlan) ratePlan).calculatePrice(room, checkIn, checkOut, companyCode);
 68	        } else {
 69	            priceCalc = ratePlan.calculatePrice(room, checkIn, checkOut);
 70	        }
 71	
 72	        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
 73	
 74	        // Create reservation
 75	        Reservation reservation = ReservationRepository.create(
 76	            roomNumber,
 77	            guestName,
 78	            guestEmail,
 79	            guestCpf,
 80	            checkIn,
 81	            checkOut,
 82	            guests,
 83	            ratePlanName,
 84	            companyCode,
 85	            nights,
 86	            priceCalc.subtotal,
 87	            priceCalc.discount,
 88	            priceCalc.total
 89	        );
 90	
 91	        return reservation;
