183	import com.pousadamarealta.database.ReservationRepository;
184	import com.pousadamarealta.database.RoomRepository;
185	import com.pousadamarealta.models.Reservation;
186	import com.pousadamarealta.models.Room;
187	import java.math.BigDecimal;
188	import java.sql.SQLException;
189	import java.time.LocalDate;
190	import java.time.YearMonth;
191	import java.time.format.DateTimeFormatter;
192	import java.util.List;
193	
194	public class ReportService {
195	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd");
196	
197	    public static String generateOccupancyReport(LocalDate date) throws SQLException {
198	        StringBuilder csv = new StringBuilder();
199	        csv.append("room,type,reservation,check_in,check_out\n");
200	
201	        List<Reservation> reservations = ReservationRepository.findByDateAndPaid(date);
202	        for (Reservation res : reservations) {
203	            Room room = RoomRepository.findById(res.roomNumber);
204	            if (room != null) {
205	                csv.append(res.roomNumber).append(",");
206	                csv.append(room.type).append(",");
207	                csv.append(res.id).append(",");
208	                csv.append(res.checkIn.format(DATE_FORMAT)).append(",");
209	                csv.append(res.checkOut.format(DATE_FORMAT)).append("\n");
210	            }
211	        }
212	
213	        int occupiedRooms = reservations.stream()
214	            .map(r -> r.roomNumber)
215	            .distinct()
216	            .toArray()
217	            .length;
218	        int totalRooms = (int) RoomRepository.findAll().stream().count();
219	
220	        csv.append("total,").append(occupiedRooms).append("/").append(totalRooms).append("\n");
221	
222	        return csv.toString();
223	    }
224	
225	    public static String generateRevenueReport(YearMonth month) throws SQLException {
226	        StringBuilder csv = new StringBuilder();
227	        csv.append("reservation,room,check_in,check_out,status,amount\n");
228	
229	        List<Reservation> reservations = ReservationRepository.findByMonthAndPaid(month.getYear(), month.getMonthValue());
230	        BigDecimal totalAmount = BigDecimal.ZERO;
231	
232	        for (Reservation res : reservations) {
233	            BigDecimal amount = res.amountPaid;
234	            if (res.refund != null && res.refund.compareTo(BigDecimal.ZERO) > 0) {
235	                amount = amount.subtract(res.refund);
236	            }
237	
238	            if (amount.compareTo(BigDecimal.ZERO) > 0) {
239	                csv.append(res.id).append(",");
240	                csv.append(res.roomNumber).append(",");
241	                csv.append(res.checkIn.format(DATE_FORMAT)).append(",");
242	                csv.append(res.checkOut.format(DATE_FORMAT)).append(",");
243	                csv.append(res.status).append(",");
244	                csv.append(String.format("%.2f", amount)).append("\n");
245	                totalAmount = totalAmount.add(amount);
246	            }
247	        }
248	
249	        csv.append("total,").append(String.format("%.2f", totalAmount)).append("\n");
250	
251	        return csv.toString();
252	    }
253	}
