277	        receipt.append("Entrada: ").append(reservation.checkIn.format(DATE_FORMAT)).append(" | ");
278	        receipt.append("Saída: ").append(reservation.checkOut.format(DATE_FORMAT)).append(" | ");
279	        receipt.append(reservation.nights).append(reservation.nights == 1 ? " diária" : " diárias").append("\n");
280	        receipt.append("Diárias: ").append(formatCurrency(reservation.subtotal)).append("\n");
281	
282	        if (reservation.discount.compareTo(BigDecimal.ZERO) > 0) {
283	            receipt.append("Desconto: ").append(formatCurrency(reservation.discount)).append("\n");
284	        }
285	
286	        receipt.append("Total: ").append(formatCurrency(reservation.total)).append("\n");
287	
288	        return receipt.toString();
289	    }
290	
291	    private static String formatCurrency(BigDecimal value) {
292	        return "R$ " + String.format("%.2f", value).replace(".", ",");
293	    }
294	
295	    private static String formatCpf(String cpf) {
296	        if (cpf == null || cpf.length() != 11) {
297	            return cpf;
298	        }
299	        return String.format("%s.%s.%s-%s", cpf.substring(0, 3), cpf.substring(3, 6), cpf.substring(6, 9), cpf.substring(9));
300	    }
301	}

