     7	public class SeasonalHelper {
     8	    public static boolean isHighSeason(LocalDate date) {
     9	        Month month = date.getMonth();
    10	
    11	        if (month == Month.JULY) {
    12	            return true;
    13	        }
    14	
    15	        if (month == Month.DECEMBER) {
    16	            return date.getDayOfMonth() >= 15;
    17	        }
    18	
    19	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
    20	            return true;
    21	        }
    22	
    23	        return false;
    24	    }
    25	
    26	    public static BigDecimal applySeasonalRate(BigDecimal nightlyRate, LocalDate date) {
    27	        if (isHighSeason(date)) {
    28	            return nightlyRate.multiply(new BigDecimal("1.20"));
    29	        }
    30	        return nightlyRate;
    31	    }
    32	
    33	    public static BigDecimal roundHalfEven(BigDecimal value) {
    34	        return value.setScale(2, java.math.RoundingMode.HALF_EVEN);
    35	    }
    36	}
