    21	        long nights = ChronoUnit.DAYS.between(checkIn, checkOut);
    22	        BigDecimal subtotal = BigDecimal.ZERO;
    23	
    24	        for (int i = 0; i < nights; i++) {
    25	            LocalDate nightDate = checkIn.plusDays(i);
    26	            BigDecimal nightlyRate = SeasonalHelper.applySeasonalRate(room.nightlyRate, nightDate);
