     8	
     9	public class Database {
    10	    private static HikariDataSource dataSource;
    11	
    12	    public static void initialize(String url, String user, String password) throws SQLException {
    13	        HikariConfig config = new HikariConfig();
    14	        config.setJdbcUrl(url);
    15	        config.setUsername(user);
    16	        config.setPassword(password);
    17	        config.setMaximumPoolSize(10);
    18	        dataSource = new HikariDataSource(config);
    19	
    20	        initializeSchema();
    21	    }
    22	
    23	    private static void initializeSchema() throws SQLException {
    24	        try (Connection conn = dataSource.getConnection();
    25	             Statement stmt = conn.createStatement()) {
    26	
    27	            String schema = """
    28	                CREATE TABLE IF NOT EXISTS rooms (
    29	                    number INTEGER PRIMARY KEY,
    30	                    type VARCHAR(20) NOT NULL,
    31	                    capacity INTEGER NOT NULL,
    32	                    nightly_rate DECIMAL(10, 2) NOT NULL
    33	                );
    34	
    35	                CREATE TABLE IF NOT EXISTS reservations (
    36	                    id SERIAL PRIMARY KEY,
    37	                    room_number INTEGER NOT NULL REFERENCES rooms(number),
    38	                    guest_name VARCHAR(255) NOT NULL,
    39	                    guest_email VARCHAR(255) NOT NULL,
    40	                    guest_cpf VARCHAR(14) NOT NULL,
    41	                    check_in DATE NOT NULL,
    42	                    check_out DATE NOT NULL,
    43	                    guests INTEGER NOT NULL,
    44	                    rate_plan VARCHAR(50) NOT NULL,
    45	                    company_code VARCHAR(50),
    46	                    nights INTEGER NOT NULL,
    47	                    subtotal DECIMAL(10, 2) NOT NULL,
    48	                    discount DECIMAL(10, 2) NOT NULL,
    49	                    total DECIMAL(10, 2) NOT NULL,
    50	                    status VARCHAR(20) NOT NULL,
    51	                    amount_paid DECIMAL(10, 2) NOT NULL DEFAULT 0,
    52	                    refund DECIMAL(10, 2),
    53	                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    54	                    CONSTRAINT check_guests CHECK (guests >= 1),
    55	                    CONSTRAINT check_nights CHECK (nights >= 1),
    56	                    CONSTRAINT check_dates CHECK (check_out > check_in)
    57	                );
    58	
    59	                CREATE TABLE IF NOT EXISTS messages (
    60	                    id SERIAL PRIMARY KEY,
    61	                    channel VARCHAR(50) NOT NULL,
    62	                    recipient VARCHAR(255) NOT NULL,
    63	                    subject VARCHAR(255) NOT NULL,
    64	                    body TEXT NOT NULL,
    65	                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    66	                );
    67	
    68	                CREATE INDEX IF NOT EXISTS idx_reservations_room_dates ON reservations(room_number, check_in, check_out);
    69	                CREATE INDEX IF NOT EXISTS idx_reservations_status ON reservations(status);
    70	                CREATE INDEX IF NOT EXISTS idx_messages_channel ON messages(channel);
    71	                """;
    72	
    73	            for (String statement : schema.split(";")) {
    74	                if (!statement.trim().isEmpty()) {
    75	                    stmt.execute(statement);
    76	                }
    77	            }
    78	        }
    79	    }
    80	
    81	    public static Connection getConnection() throws SQLException {
    82	        return dataSource.getConnection();
    83	    }
    84	
    85	    public static void shutdown() {
    86	        if (dataSource != null) {
    87	            dataSource.close();
    88	        }
    89	    }
    90	}
